<?php
require_once __DIR__.'/../includes/bootstrap.php';admin_required();$id=filter_input(INPUT_GET,'event_id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Valid event_id required.');}$pdo=db();$s=$pdo->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$ev=$s->fetch();if(!$ev){http_response_code(404);exit('Event not found.');}$s=$pdo->prepare('SELECT u.full_name,u.email,r.registered_at,r.status FROM registrations r JOIN users u ON u.id=r.user_id WHERE r.event_id=? ORDER BY r.registered_at DESC');$s->execute([$id]);$rows=$s->fetchAll();$pageTitle='Registrations';require __DIR__.'/../includes/header.php';?><a href="index.php">← Admin dashboard</a><h1 class="fw-bold mt-3">Registrations: <?=e($ev['title'])?></h1><div class="panel table-responsive mt-4"><table class="table"><thead><tr><th>Student</th><th>Email</th><th>Registered</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4">No registrations yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e(date('d M Y H:i',strtotime($r['registered_at'])))?></td><td><?=e(ucfirst($r['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>